import './Footer.css';
const Footer=()=> <footer className="footer"><div className="footer-top"><div><span className="footer-kicker">Have a project in mind?</span><h2>Let’s make something<br/><i>remarkable.</i></h2><a className="footer-cta" href="mailto:info@buildwebcanada.com">Start a conversation <FiArrowUpRight/></a></div><div className="footer-links"><div><span>Explore</span><a href="#home">Home</a><a href="#services">Services</a><a href="/projects">Projects</a><a href="#about">About</a></div><div><span>Get in touch</span><a href="mailto:info@buildwebcanada.com">info@buildwebcanada.com</a><a href="tel:+17789969060">+1 (778) 996 9060</a><a href="tel:+17789303838">+1 (778) 930 3838</a><p>Vancouver & Calgary<br/>Canada</p></div></div></div><div className="footer-bottom"><p>© {new Date().getFullYear()} BuildWebCanada. All rights reserved.</p><div className="social-icons"><a aria-label="GitHub" href="https://github.com/sanjeev-mehta" target="_blank" rel="noopener noreferrer"><FaGithub/></a><a aria-label="LinkedIn" href="https://www.linkedin.com/in/sanjeev-mehta-ios/" target="_blank" rel="noopener noreferrer"><FaLinkedinIn/></a><a aria-label="Facebook" href="https://facebook.com/yourprofile" target="_blank" rel="noopener noreferrer"><FaFacebookF/></a></div><p>Built with intent.</p></div></footer>;
export default Footer;
